data.query:
query ($workcenterId: String!) {
  productionSetupOutput(where: {workcenterId: {_eq: $workcenterId}}) {
    total
    edges {
      node {
        id
        productNumberRevision
        outputId
        counterInput
        cycleTime
        distributionQuantity
        idealRate
        lastProductionQuantity
        lastScrapQuantity
        producedQuantity
        remainingBalance
        scrappedQuantity
        setupRate
        standardQuantity
        standardRate
        unitPerCycle
        autoProduction
        containerType
        distributionStatus
        externalId
        lastScrapReasonExt
        operationCode
        operationNumber
        productId
        productName
        productNumber
        productOperationId
        productRevision
        workOrderNumber
        dueAt
        scheduledStartAt
        startAt
        customData
        workcenterId
        approvedWorkcenterId
        lastScrapReasonId
        productionSetupId

      }
    }
  }
  productionSetup(where: {workcenterId: {_eq: $workcenterId}}){
    edges{
      node{
				id
        productionRunId
        workcenterId
      }
    }
  }
  workcenter(where:{id:{ _eq: $workcenterId}}){
    edges{
      node{
        shiftGroup{
          shifts{
            edges{
              node{
                id
                name
                creditAtStart
                monday
                tuesday
                wednesday
                thursday
                friday
                saturday
                sunday
                startHour
                startMinute
                endHour
                endMinute            
              }
            }
          }
        }
        currentWorkcenterHistory{
          modeId
          eventId          
        }
      }
    }
  }
  setting(where:{id:{_eq: "TimeZone"}}){
    edges{
      node{
        defaultValue
      }
    }
  }
}

data.transform:
(
  $defaultToZero := function($value){ $coalesce([$value, 0]) };
  $outputs := productionSetupOutput.edges.node;
  $now := $moment().format();
  $runId := $cuid();
  $workcenterHistoryId := $cuid();

  $shift := $executeTransform(
    "getShift",
    {
      "date": $now,
      "shifts": workcenter.edges.node.shiftGroup.shifts.edges.node,
      "timeZone": setting.edges.node.defaultValue
    }
  );

  {
    "shift": $shift,
    "runPayload":{
      "create": {
        "id": $runId,
        "idealAggregate": $sum([$outputs.idealRate.($defaultToZero($))]),
        "standardAggregate": $sum([$outputs.standardRate.($defaultToZero($))]),
        "averageCycleTime": 0,
        "changeoverAggregate": $sum([$outputs.setupRate.($defaultToZero($))]),
        "runCrewSize": productionSetup.edges.node.crewSize,
        "workcenterId":productionSetup.edges.node.workcenterId,
        "startAt": $now,
        "productionSetupId": productionSetup.edges.node.id,
        "totalRequired": $sum([$outputs.distributionQuantity.($defaultToZero($))]),
        "excludedProduction": 0,
        "excludedScrap":0,
