      "where":{ "id": productionSetup.edges.node.workcenterId },
      "update":{
        "currentWorkcenterHistoryId": $workcenterHistoryId
      }
    }
  } 

)

data.mutation:
mutation (
  $runPayload: [ProductionRunCreatePayloadInput!]!,
  $setupPayload: [ProductionSetupUpdatePayloadInput!]!
  $workcenterHistoryPayload: [WorkcenterHistoryCreatePayloadInput!]!
  $workcenterPayload: [WorkcenterUpdatePayloadInput!]!
  $workOrderDistributionPayload: [WorkOrderProcessDistributionCreatePayloadInput!]!
){
  createProductionRun(payload: $runPayload){ id }
  updateProductionSetup(payload: $setupPayload){ id }  
  createWorkcenterHistory(payload: $workcenterHistoryPayload){ id }
  updateWorkcenter(payload:$workcenterPayload ){ id }
  createWorkOrderProcessDistribution(payload: $workOrderDistributionPayload) { id }
}

