}

data.transform:
(

  $workcenterHistoryId := $cuid();
  $calculateSeconds := function($startBound, $endBound, $mode){(

    $modeStart := $mode.occurAt? $moment($mode.occurAt);
    $modeEnd := $mode.endAt? $moment($mode.endAt);

    $endBoundObj := $moment($endBound);
    $startBoundObj := $moment($startBound);

    $start := $mode.occurAt and $modeStart.isAfter($startBound)? $modeStart : $startBoundObj;
    $end := $mode.endAt and $modeEnd.isBefore($endBound)? $modeEnd : $endBoundObj;

    $isNilOrEmpty($mode.occurAt) and $isNilOrEmpty($mode.endAt)? 
      $throw("Mode has no occurAt or endAt", $mode) :
      $end.diff($start, "seconds")   

  )};
  $time := $calculateSeconds(productionRun.edges.node.startAt, $state.context.endAt, ?);

  $totalProduced := $coalesce( [$sum(productionHistory.edges.node[transactionTypeId="Production Add" and includeInProductionCounts].quantity), 0 ]);
  $totalScrap := $coalesce([$sum(productionHistory.edges.node[transactionTypeId="Scrap Add" and includeInProductionCounts].quantity), 0]);
  $totalProduction := $totalProduced + $totalScrap;

  $totalExcludedProduced := $coalesce( [$sum(productionHistory.edges.node[transactionTypeId="Production Add" and includeInProductionCounts=false].quantity), 0 ]);
  $totalExcludedScrap := $coalesce([$sum(productionHistory.edges.node[transactionTypeId="Scrap Add" and includeInProductionCounts = false].quantity), 0]);

  $runCrewSize := $coalesce([productionRun.edges.node.runCrewSize, 0]);
  $crewAggregate := $coalesce([productionRun.edges.node.crewAggregate, 0]);
  $standardRate := productionRun.edges.node.standardAggregate;

  $end := $moment( $state.context.endAt );
  $start := $moment( productionRun.edges.node.startAt );
  $duration := $end.diff($start, "seconds");

  $idealRateSeconds := productionRun.edges.node.idealAggregate / 3600;
  $now := $moment().format();

  /* Mode Type is changeover */
  $changeoverTime := $reduce(
    [workcenterHistory.edges.node[modeType.changeover]],
    function($acc, $crr){ $acc + $time($crr) },
    0
  );
   /* Event Type is plannedDowntime */
  $plannedDowntime := $reduce(
    [workcenterHistory.edges.node[event.eventType.plannedDowntime]],
    function($acc, $crr){ $acc + $time($crr) },
    0
  );
   /* Event Type is unplannedDowntime */
  $unplannedDowntime := $reduce(
    [workcenterHistory.edges.node[event.eventType.unplannedDowntime]],
    function($acc, $crr){ $acc + $time($crr) },
    0
  );
  $downTime := $unplannedDowntime + $plannedDowntime;
  $runTime := $duration - $downTime;
  $shift := $executeTransform(
    "getShift",
    {
      "date": $state.context.endAt,
      "shifts": $state.context.workcenter.edges.node.shiftGroup.shifts.edges.node,
      "timeZone": $state.context.setting.edges.node.defaultValue
    }
    );

  $plannedProductionTime := $duration - $plannedDowntime;
  $availability := $duration? $runTime / $plannedProductionTime : 1;
  $pref := $runTime > 0? 
    ($idealRateSeconds? $totalProduction / $runTime / $idealRateSeconds : 1 ) 
    : 0 ;
  $quality := $totalProduction=0? 1 : $totalProduced / $totalProduction;

  $oee := $availability * $pref * $quality;


  {
    "runPayload":{
      "where": { "id": productionRun.edges.node.id},
      "update":  {
        "produced": $totalProduced,
        "scrap": $totalScrap,
        "averageCycleTime": $totalProduction > 0? $runTime / $totalProduction : 0, 
        "earnedLaborHours": $standardRate? 
          ($totalProduced / $standardRate * $crewAggregate) : 
          0,
        "earnedMachineHours": $standardRate? $totalProduced / $standardRate : 0,
        "excludedScrap": $totalExcludedScrap,
        "excludedProduction": $totalExcludedProduced,
        "totalProduction": $totalProduction,
        "endAt": $state.context.endAt,
        "duration": $duration,
        "quality": $quality,
        "performance": $pref,
        "runTime": $runTime,
        "changeoverTime": $changeoverTime,
        "plannedDowntime": $plannedDowntime,
        "unplannedDowntime": $unplannedDowntime,
        "workcenterId": $state.context.productionSetup.edges.node.workcenterId,
        "actualLaborHours": $runtTime *  $runCrewSize,
        "availability": $availability,
        "oee": $oee
      }
    },
    "setupPayload":{
      "where": { "id": $state.context.productionSetup.edges.node.id },
      "update":{ "productionRunId": null }
    },
    "workcenterHistoryPayload":[
      {
        "create": $merge([
          { 
            "id": $cuid(),
            "transactionTypeId": "Production Setup clear",
            "productionRunId": productionRun.edges.node.id,
            "workcenterId": $state.context.productionSetup.edges.node.workcenterId,
            "creditedAt": $coalesce([ $shift.creditAt, $moment().startOf("day").format()]),
            "shiftId": $shift.id,
            "occurAt": $now,
            "endAt": $now,
            "duration": 0
          },
          $state.context.workcenter.edges.node.currentWorkcenterHistory
        ])
      },
      {
        "create": $merge([
          { 
            "id": $workcenterHistoryId,
            "transactionTypeId": "Mode Change",
            "workcenterId": $state.context.productionSetup.edges.node.workcenterId,
            "creditedAt": $coalesce([ $shift.creditAt, $moment().startOf("day").format()]),
            "shiftId": $shift.id,
            "occurAt": $now
          },
          $state.context.workcenter.edges.node.currentWorkcenterHistory
        ])
      }
    ],
    "workcenterPayload":[{
      "where":{ "id": $state.context.productionSetup.edges.node.workcenterId },
      "update":{
        "currentWorkcenterHistoryId": $workcenterHistoryId
      }
    }]
  }


)

